final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Scheduled account closure workflow: an hourly Amazon EventBridge rule starts an EXPRESS
  AWS Step Functions state machine that pages through the AWS Organization, selects the accounts
  tagged "organizations:account-closure = REQUESTED", describes each of them, closes the ones
  that are ACTIVE, and rewrites the tag to ACKNOWLEDGED so the next run skips them. Every
  execution is logged, including execution data, to an encrypted CloudWatch log group retained
  for 365 days. Every resource this workflow needs is created by this template.

Resources:

  # -----------------------------------------------------------------------------------------
  # Customer managed KMS key used to encrypt the workflow execution logs at rest.
  # -----------------------------------------------------------------------------------------
  AccountClosureLogKey:
    Type: AWS::KMS::Key
    Properties:
      Description: Encrypts the CloudWatch log group that stores the account closure workflow execution data.
      EnableKeyRotation: true
      KeyPolicy:
        Version: '2012-10-17'
        Id: account-closure-logs
        Statement:
          - Sid: AllowAccountRootFullControl
            Effect: Allow
            Principal:
              AWS: !Sub 'arn:${AWS::Partition}:iam::${AWS::AccountId}:root'
            Action: 'kms:*'
            Resource: '*'
          - Sid: AllowCloudWatchLogsInThisRegion
            Effect: Allow
            Principal:
              Service: !Sub 'logs.${AWS::Region}.amazonaws.com'
            Action:
              - 'kms:Encrypt*'
              - 'kms:Decrypt*'
              - 'kms:ReEncrypt*'
              - 'kms:GenerateDataKey*'
              - 'kms:Describe*'
            Resource: '*'
            Condition:
              ArnLike:
                'kms:EncryptionContext:aws:logs:arn': !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:*'

  # -----------------------------------------------------------------------------------------
  # Execution log group. Step Functions vended logs require the group name to start with
  # /aws/vendedlogs/, and the execution history must survive stack deletion or replacement.
  # -----------------------------------------------------------------------------------------
  AccountClosureLogGroup:
    Type: AWS::Logs::LogGroup
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      LogGroupName: !Sub '/aws/vendedlogs/states/${AWS::StackName}-account-closure'
      RetentionInDays: 365
      KmsKeyId: !GetAtt AccountClosureLogKey.Arn

  # -----------------------------------------------------------------------------------------
  # Least privilege execution role for the account closure state machine.
  # -----------------------------------------------------------------------------------------
  AccountClosureStateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the EXPRESS account closure state machine.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Sid: AllowStepFunctionsToAssumeRole
            Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: OrganizationsAccountClosure
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              # ListAccounts has no resource type and ListTagsForResource is not scopeable at
              # template time, so "*" is the only valid resource for these two read operations.
              - Sid: OrganizationsListOperations
                Effect: Allow
                Action:
                  - organizations:ListAccounts
                  - organizations:ListTagsForResource
                Resource: '*'
              # These actions support the Organizations "account" resource type, so they are
              # narrowed to account ARNs owned by the account that deploys this stack. No account
              # or organization id is hardcoded here.
              - Sid: OrganizationsAccountOperations
                Effect: Allow
                Action:
                  - organizations:DescribeAccount
                  - organizations:CloseAccount
                  - organizations:TagResource
                Resource: !Sub 'arn:${AWS::Partition}:organizations::${AWS::AccountId}:account/*'
        - PolicyName: StepFunctionsExecutionLogging
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              # Only the vended logs delivery permissions are granted. The log group is created
              # by this template, so logs:CreateLogGroup / logs:CreateLogStream are not required.
              # These delivery APIs are not resource scopeable, hence "*".
              - Sid: VendedLogsDelivery
                Effect: Allow
                Action:
                  - logs:CreateLogDelivery
                  - logs:GetLogDelivery
                  - logs:UpdateLogDelivery
                  - logs:DeleteLogDelivery
                  - logs:ListLogDeliveries
                  - logs:DescribeLogGroups
                  - logs:PutResourcePolicy
                  - logs:DescribeResourcePolicies
                Resource: '*'
              - Sid: EncryptAndReadExecutionLogs
                Effect: Allow
                Action:
                  - 'kms:GenerateDataKey*'
                  - kms:Decrypt
                Resource: !GetAtt AccountClosureLogKey.Arn

  # -----------------------------------------------------------------------------------------
  # EXPRESS state machine: paginate accounts, filter on the closure tag, describe, close,
  # acknowledge, with throttling / eventual consistency retries and per-account error capture.
  # -----------------------------------------------------------------------------------------
  AccountClosureStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineType: EXPRESS
      RoleArn: !GetAtt AccountClosureStateMachineRole.Arn
      LoggingConfiguration:
        Level: ALL
        IncludeExecutionData: true
        Destinations:
          - CloudWatchLogsLogGroup:
              # Step Functions expects the destination in the form ...:log-group:<name>:*
              LogGroupArn: !Sub '${AccountClosureLogGroup.Arn}:*'
      DefinitionString: !Sub |-
        {
          "Comment": "Closes AWS Organizations accounts tagged organizations:account-closure=REQUESTED. Invoked every hour by Amazon EventBridge.",
          "StartAt": "ListAccounts",
          "TimeoutSeconds": 300,
          "States": {
            "ListAccounts": {
              "Type": "Task",
              "Comment": "List one page of the organization. MaxResults is deliberately small so the run stays inside the EXPRESS 5 minute execution limit.",
              "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:listAccounts",
              "Parameters": {
                "MaxResults": 20,
                "NextToken.$": "$.page.nextToken"
              },
              "ResultPath": "$.listAccountsResult",
              "Next": "CapturePage",
              "Retry": [
                {"ErrorEquals": ["Organizations.ThrottlingException", "Organizations.TooManyRequestsException", "Organizations.ConcurrentModificationException"], "IntervalSeconds": 2, "MaxAttempts": 6, "BackoffRate": 2},
                {"ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 2, "MaxAttempts": 3, "BackoffRate": 2}
              ],
              "Catch": [
                {"ErrorEquals": ["States.ALL"], "ResultPath": "$.errorInfo", "Next": "WorkflowFailed"}
              ]
            },
            "CapturePage": {
              "Type": "Pass",
              "Comment": "Carry the current page of accounts and its continuation token forward. The token key is omitted once the listing is exhausted.",
              "Parameters": {
                "accounts.$": "$.listAccountsResult.Accounts",
                "nextToken.$": "$.listAccountsResult.NextToken"
              },
              "ResultPath": "$.page",
              "Next": "HasAccounts"
            },
            "HasAccounts": {
              "Type": "Choice",
              "Choices": [
                {"Variable": "$.page.accounts", "IsPresent": true, "Next": "ProcessPage"}
              ],
              "Default": "CheckNextToken"
            },
            "ProcessPage": {
              "Type": "Map",
              "Comment": "Inline Map state (Distributed Map is not available in EXPRESS workflows). MaxConcurrency is capped low so Organizations throttling stays bounded.",
              "ItemsPath": "$.page.accounts",
              "MaxConcurrency": 2,
              "Iterator": {
                "StartAt": "ListTagsForResource",
                "States": {
                  "ListTagsForResource": {
                    "Type": "Task",
                    "Comment": "Read the tags of this account so the closure request tag can be evaluated.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:listTagsForResource",
                    "Parameters": {
                      "ResourceId.$": "$.Id"
                    },
                    "ResultPath": "$.tags",
                    "Next": "HasTags",
                    "Retry": [
                      {"ErrorEquals": ["Organizations.ThrottlingException", "Organizations.TooManyRequestsException", "Organizations.ConcurrentModificationException"], "IntervalSeconds": 2, "MaxAttempts": 4, "BackoffRate": 2},
                      {"ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 2, "MaxAttempts": 3, "BackoffRate": 2}
                    ],
                    "Catch": [
                      {"ErrorEquals": ["States.ALL"], "ResultPath": "$.error", "Next": "RecordAccountFailure"}
                    ]
                  },
                  "HasTags": {
                    "Type": "Choice",
                    "Comment": "Accounts without any tags are skipped without further API calls.",
                    "Choices": [
                      {"Variable": "$.tags.Tags", "IsPresent": true, "Next": "EvaluateTagArray"}
                    ],
                    "Default": "SkipNotTagged"
                  },
                  "EvaluateTagArray": {
                    "Type": "Map",
                    "Comment": "Inline Map over the account tags. Every tag that exactly matches the closure request key and value emits a sentinel element.",
                    "ItemsPath": "$.tags.Tags",
                    "MaxConcurrency": 1,
                    "Iterator": {
                      "StartAt": "IsClosureTagRequested",
                      "States": {
                        "IsClosureTagRequested": {
                          "Type": "Choice",
                          "Comment": "Exact, case sensitive match on the tag key and value.",
                          "Choices": [
                            {
                              "And": [
                                {"Variable": "$.Key", "StringEquals": "organizations:account-closure"},
                                {"Variable": "$.Value", "StringEquals": "REQUESTED"}
                              ],
                              "Next": "ClosureTagMatched"
                            }
                          ],
                          "Default": "ClosureTagNotMatched"
                        },
                        "ClosureTagMatched": {
                          "Type": "Pass",
                          "Result": "CLOSURE_REQUESTED",
                          "ResultPath": "$",
                          "End": true
                        },
                        "ClosureTagNotMatched": {
                          "Type": "Pass",
                          "Result": "NO_MATCH",
                          "ResultPath": "$",
                          "End": true
                        }
                      }
                    },
                    "ResultPath": "$.tagChecks",
                    "Next": "EvaluateTagMatch",
                    "Catch": [
                      {"ErrorEquals": ["States.ALL"], "ResultPath": "$.error", "Next": "RecordAccountFailure"}
                    ]
                  },
                  "EvaluateTagMatch": {
                    "Type": "Pass",
                    "Comment": "Reduce the per tag results to a single boolean flag.",
                    "Parameters": {
                      "closureRequested.$": "States.ArrayContains($.tagChecks, 'CLOSURE_REQUESTED')"
                    },
                    "ResultPath": "$.tagMatch",
                    "Next": "IsTaggedForClosure"
                  },
                  "IsTaggedForClosure": {
                    "Type": "Choice",
                    "Comment": "Only accounts carrying organizations:account-closure = REQUESTED continue.",
                    "Choices": [
                      {"Variable": "$.tagMatch.closureRequested", "BooleanEquals": true, "Next": "DescribeAccount"}
                    ],
                    "Default": "SkipNotTagged"
                  },
                  "DescribeAccount": {
                    "Type": "Task",
                    "Comment": "Read the authoritative status of the account before closing it.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:describeAccount",
                    "Parameters": {
                      "AccountId.$": "$.Id"
                    },
                    "ResultPath": "$.account",
                    "Next": "IsAccountActive",
                    "Retry": [
                      {"ErrorEquals": ["Organizations.ThrottlingException", "Organizations.TooManyRequestsException", "Organizations.ConcurrentModificationException"], "IntervalSeconds": 2, "MaxAttempts": 6, "BackoffRate": 2},
                      {"ErrorEquals": ["Organizations.AccountNotFoundException", "Organizations.AccountNotRegisteredException"], "IntervalSeconds": 5, "MaxAttempts": 4, "BackoffRate": 2},
                      {"ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 2, "MaxAttempts": 3, "BackoffRate": 2}
                    ],
                    "Catch": [
                      {"ErrorEquals": ["States.ALL"], "ResultPath": "$.error", "Next": "RecordAccountFailure"}
                    ]
                  },
                  "IsAccountActive": {
                    "Type": "Choice",
                    "Comment": "Only ACTIVE accounts are closed. SUSPENDED, PENDING_CLOSURE and any other status is skipped.",
                    "Choices": [
                      {"Variable": "$.account.Account.Status", "StringEquals": "ACTIVE", "Next": "CloseAccount"}
                    ],
                    "Default": "SkipNotActive"
                  },
                  "CloseAccount": {
                    "Type": "Task",
                    "Comment": "Close the account with an explicit task timeout so a hung call cannot consume the whole EXPRESS execution.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:closeAccount",
                    "Parameters": {
                      "AccountId.$": "$.Id"
                    },
                    "TimeoutSeconds": 60,
                    "ResultPath": "$.closeResult",
                    "Next": "TagAccountAcknowledged",
                    "Retry": [
                      {"ErrorEquals": ["Organizations.ThrottlingException", "Organizations.TooManyRequestsException", "Organizations.ConcurrentModificationException"], "IntervalSeconds": 2, "MaxAttempts": 6, "BackoffRate": 2},
                      {"ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 2, "MaxAttempts": 3, "BackoffRate": 2}
                    ],
                    "Catch": [
                      {"ErrorEquals": ["States.ALL"], "ResultPath": "$.error", "Next": "RecordAccountFailure"}
                    ]
                  },
                  "TagAccountAcknowledged": {
                    "Type": "Task",
                    "Comment": "Rewrite the closure tag so the next hourly run does not attempt the closure again.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:tagResource",
                    "Parameters": {
                      "ResourceId.$": "$.Id",
                      "Tags": [
                        {"Key": "organizations:account-closure", "Value": "ACKNOWLEDGED"}
                      ]
                    },
                    "ResultPath": "$.tagResult",
                    "Next": "RecordClosed",
                    "Retry": [
                      {"ErrorEquals": ["Organizations.ThrottlingException", "Organizations.TooManyRequestsException", "Organizations.ConcurrentModificationException"], "IntervalSeconds": 2, "MaxAttempts": 6, "BackoffRate": 2},
                      {"ErrorEquals": ["Organizations.AccountNotFoundException", "Organizations.AccountNotRegisteredException"], "IntervalSeconds": 5, "MaxAttempts": 4, "BackoffRate": 2},
                      {"ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 2, "MaxAttempts": 3, "BackoffRate": 2}
                    ],
                    "Catch": [
                      {"ErrorEquals": ["States.ALL"], "ResultPath": "$.error", "Next": "RecordAccountFailure"}
                    ]
                  },
                  "RecordClosed": {
                    "Type": "Pass",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "action": "CLOSED_AND_ACKNOWLEDGED"
                    },
                    "End": true
                  },
                  "SkipNotTagged": {
                    "Type": "Pass",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "action": "SKIPPED_NOT_TAGGED"
                    },
                    "End": true
                  },
                  "SkipNotActive": {
                    "Type": "Pass",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "status.$": "$.account.Account.Status",
                      "action": "SKIPPED_NOT_ACTIVE"
                    },
                    "End": true
                  },
                  "RecordAccountFailure": {
                    "Type": "Pass",
                    "Comment": "Captures the failure for this single account so the rest of the page is still processed.",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "action": "FAILED",
                      "error.$": "$.error.Error",
                      "cause.$": "$.error.Cause"
                    },
                    "End": true
                  }
                }
              },
              "ResultPath": "$.pageResults",
              "Next": "CheckNextToken",
              "Catch": [
                {"ErrorEquals": ["States.ALL"], "ResultPath": "$.errorInfo", "Next": "WorkflowFailed"}
              ]
            },
            "CheckNextToken": {
              "Type": "Choice",
              "Comment": "Loop back into ListAccounts while Organizations keeps returning a non-empty NextToken.",
              "Choices": [
                {
                  "And": [
                    {"Variable": "$.page.nextToken", "IsPresent": true},
                    {"Variable": "$.page.nextToken", "StringGreaterThan": ""}
                  ],
                  "Next": "ListAccounts"
                }
              ],
              "Default": "WorkflowSucceeded"
            },
            "WorkflowSucceeded": {
              "Type": "Pass",
              "Comment": "Terminal success state. The per account outcome is in the execution log.",
              "Parameters": {
                "status": "COMPLETED",
                "accountResults.$": "$.pageResults"
              },
              "End": true
            },
            "WorkflowFailed": {
              "Type": "Fail",
              "ErrorPath": "$.errorInfo.Error",
              "CausePath": "$.errorInfo.Cause"
            }
          }
        }

  # -----------------------------------------------------------------------------------------
  # Invocation role that lets the hourly EventBridge rule start the state machine, and nothing else.
  # -----------------------------------------------------------------------------------------
  AccountClosureEventBridgeRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows the hourly Amazon EventBridge rule to start the account closure state machine.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Sid: AllowEventBridgeToAssumeRole
            Effect: Allow
            Principal:
              Service: events.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: StartAccountClosureExecution
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: StartTheAccountClosureStateMachine
                Effect: Allow
                Action:
                  - states:StartExecution
                Resource: !Ref AccountClosureStateMachine

  # -----------------------------------------------------------------------------------------
  # Hourly schedule that invokes the EXPRESS workflow asynchronously.
  # -----------------------------------------------------------------------------------------
  AccountClosureScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Description: Runs the account closure EXPRESS workflow once every hour.
      ScheduleExpression: 'rate(1 hour)'
      State: ENABLED
      Targets:
        - Id: AccountClosureStateMachineTarget
          Arn: !Ref AccountClosureStateMachine
          RoleArn: !GetAtt AccountClosureEventBridgeRole.Arn

Outputs:
  AccountClosureStateMachineArn:
    Description: ARN of the account closure state machine. Use it for a manual verification execution.
    Value: !Ref AccountClosureStateMachine
    Export:
      Name: !Sub '${AWS::StackName}-AccountClosureStateMachineArn'

  AccountClosureStateMachineName:
    Description: Name of the account closure state machine.
    Value: !GetAtt AccountClosureStateMachine.Name
    Export:
      Name: !Sub '${AWS::StackName}-AccountClosureStateMachineName'

  AccountClosureLogGroupName:
    Description: Name of the CloudWatch log group that stores the execution data.
    Value: !Ref AccountClosureLogGroup
    Export:
      Name: !Sub '${AWS::StackName}-AccountClosureLogGroupName'

  AccountClosureScheduleRuleName:
    Description: Name of the hourly EventBridge rule.
    Value: !Ref AccountClosureScheduleRule
    Export:
      Name: !Sub '${AWS::StackName}-AccountClosureScheduleRuleName'

  AccountClosureScheduleRuleArn:
    Description: ARN of the hourly EventBridge rule.
    Value: !GetAtt AccountClosureScheduleRule.Arn
    Export:
      Name: !Sub '${AWS::StackName}-AccountClosureScheduleRuleArn'

AWSTemplateFormatVersion: '2010-09-09'
Description: >
  Amazon Verified Permissions policy store that implements Cedar-based access control for a
  bookstore application. Defines a strict-validated Bookstore schema (Role, User, Book entities
  plus View and ViewWithPremiumOffers actions requiring a caller region in the request context),
  seven static Cedar policies (admin grant, named-admin forbid, publisher ownership, point grant,
  customer premium-offer tenure rules, and a US-only region gate), and publishes the policy store
  identifier to SSM Parameter Store for downstream consumption. All dependencies are created
  within this template.

Resources:

  ###########################################################################################
  # Policy store: container for the Cedar schema and all static policies (STRICT validation)
  ###########################################################################################
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  ###########################################################################################
  # Policy 1 - Any principal in the Admin role may view any book
  ###########################################################################################
  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book.
          Statement: |-
            permit(
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ###########################################################################################
  # Policy 2 - Specific named administrator is explicitly forbidden (overrides Policy 1)
  ###########################################################################################
  NamedAdminForbidViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid the named administrator from viewing books.
          Statement: |-
            forbid(
              principal == Bookstore::User::"admin-blocked",
              action == Bookstore::Action::"View",
              resource
            );

  ###########################################################################################
  # Policy 3 - Publishers may view only the books they own
  ###########################################################################################
  PublisherViewOwnedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they themselves own.
          Statement: |-
            permit(
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  ###########################################################################################
  # Policy 4 - Point grant: one named user may view one named book
  ###########################################################################################
  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit one specific named user to view one specific named book.
          Statement: |-
            permit(
              principal == Bookstore::User::"jane-doe",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"cedar-craft"
            );

  ###########################################################################################
  # Policy 5 - Customers with two or more years of membership may view premium offers
  ###########################################################################################
  CustomerPremiumOffersTenurePermitPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit customers with two or more years of membership to view premium offers.
          Statement: |-
            permit(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember >= 2
            };

  ###########################################################################################
  # Policy 6 - Customers with less than two years of membership are forbidden (overrides Policy 5)
  ###########################################################################################
  CustomerPremiumOffersShortTenureForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid customers with less than two years of membership from viewing premium offers.
          Statement: |-
            forbid(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember < 2
            };

  ###########################################################################################
  # Policy 7 - Region gate: neither action is permitted outside the United States
  ###########################################################################################
  UnitedStatesOnlyForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers whenever the request context region is not the United States.
          Statement: |-
            forbid(
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "US"
            };

  ###########################################################################################
  # SSM parameter publishing the policy store identifier for downstream consumption
  ###########################################################################################
  BookstorePolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Description: Identifier of the Amazon Verified Permissions policy store for the bookstore application.
      Value: !Ref BookstorePolicyStore

Outputs:

  PolicyStoreId:
    Description: The identifier of the Amazon Verified Permissions policy store.
    Value: !Ref BookstorePolicyStore

  PolicyStoreArn:
    Description: The ARN of the Amazon Verified Permissions policy store.
    Value: !GetAtt BookstorePolicyStore.Arn

  PolicyStoreIdParameterName:
    Description: The name of the SSM parameter that holds the policy store identifier.
    Value: !Ref BookstorePolicyStoreIdParameter

  PolicyStoreIdParameterArn:
    Description: The ARN of the SSM parameter that holds the policy store identifier.
    Value: !Sub 'arn:${AWS::Partition}:ssm:${AWS::Region}:${AWS::AccountId}:parameter/bookstore/verified-permissions/policy-store-id'

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Self-contained AWS AppSync GraphQL API "TodoAPIwithJs" with API key authentication,
  backed by an in-template DynamoDB table (owner-index global secondary index) and
  JavaScript (APPSYNC_JS 1.0.0) pipeline resolvers for Todo CRUD, todosByOwner query,
  and real-time create/update/delete subscriptions. No pre-existing infrastructure required.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB backing table + owner-index GSI
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  # ---------------------------------------------------------------------------
  # AppSync field-level logging: log group + role
  # ---------------------------------------------------------------------------
  AppSyncLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/appsync/apis/${GraphQLApi.ApiId}'
      RetentionInDays: 7

  AppSyncLogsRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action:
              - sts:AssumeRole
      Policies:
        - PolicyName: AppSyncCloudWatchLogsPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                # Scoped to this API's AppSync log group prefix. The concrete group ARN
                # cannot be referenced here without creating a circular dependency
                # (LogGroup -> GraphQLApi -> LogsRole -> LogGroup).
                Resource:
                  - !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/appsync/apis/*'

  # ---------------------------------------------------------------------------
  # AppSync DynamoDB data source execution role
  # ---------------------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action:
              - sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccessPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  # ---------------------------------------------------------------------------
  # GraphQL API, API key, schema
  # ---------------------------------------------------------------------------
  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncLogsRole.Arn
        FieldLogLevel: ALL
        ExcludeVerboseContent: false

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: 'API key for the TodoAPIwithJs GraphQL API'

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

        type Todo {
          id: ID!
          name: String
          description: String
          owner: String
          createdAt: String
          updatedAt: String
        }

        type TodoList {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoList
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoList
        }

        type Mutation {
          createTodo(name: String!, description: String): Todo
          updateTodo(id: ID!, name: String, description: String): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  # ---------------------------------------------------------------------------
  # Data sources
  # ---------------------------------------------------------------------------
  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoTableDataSource
      Description: 'DynamoDB data source for the Todo table'
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref 'AWS::Region'

  NoneDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: NoneDataSource
      Description: 'None data source used by subscription resolvers'
      Type: NONE

  # ---------------------------------------------------------------------------
  # Pipeline functions (JavaScript / APPSYNC_JS)
  # ---------------------------------------------------------------------------
  FnGetTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_getTodo
      Description: 'Get a single Todo item by id'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnListTodos:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_listTodos
      Description: 'List Todo items'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit || 50,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  FnTodosByOwner:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_todosByOwner
      Description: 'Query Todo items by owner using the owner-index GSI'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            index: 'owner-index',
            limit: ctx.args.limit || 50,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  FnCreateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_createTodo
      Description: 'Create a Todo item'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const identity = ctx.identity || {};
          const claims = identity.claims || {};
          const owner = identity.username || claims.sub || identity.sub || 'anonymous';
          const now = util.time.nowISO8601();

          const item = {
            id: util.autoId(),
            name: ctx.args.name,
            description: ctx.args.description,
            owner: owner,
            createdAt: now,
            updatedAt: now,
          };

          ctx.stash.todoItem = item;

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          // PutItem does not return the written item, so surface the item built in the request.
          return ctx.stash.todoItem;
        }

  FnUpdateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_updateTodo
      Description: 'Update a Todo item'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const now = util.time.nowISO8601();

          const expressionNames = { '#updatedAt': 'updatedAt' };
          const expressionValues = { ':updatedAt': now };
          const sets = ['#updatedAt = :updatedAt'];

          if (ctx.args.name !== undefined && ctx.args.name !== null) {
            expressionNames['#name'] = 'name';
            expressionValues[':name'] = ctx.args.name;
            sets.push('#name = :name');
          }

          if (ctx.args.description !== undefined && ctx.args.description !== null) {
            expressionNames['#description'] = 'description';
            expressionValues[':description'] = ctx.args.description;
            sets.push('#description = :description');
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            returnValues: 'ALL_NEW',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnDeleteTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: fn_deleteTodo
      Description: 'Delete a Todo item'
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            returnValues: 'ALL_OLD',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Query resolvers (pipeline)
  # ---------------------------------------------------------------------------
  ResolverQueryGetTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnGetTodo.FunctionId

  ResolverQueryListTodos:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnListTodos.FunctionId

  ResolverQueryTodosByOwner:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnTodosByOwner.FunctionId

  # ---------------------------------------------------------------------------
  # Mutation resolvers (pipeline)
  # ---------------------------------------------------------------------------
  ResolverMutationCreateTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnCreateTodo.FunctionId

  ResolverMutationUpdateTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnUpdateTodo.FunctionId

  ResolverMutationDeleteTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnDeleteTodo.FunctionId

  # ---------------------------------------------------------------------------
  # Subscription resolvers (NONE data source; fan-out driven by @aws_subscribe)
  # ---------------------------------------------------------------------------
  ResolverSubscriptionOnCreateTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onCreateTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  ResolverSubscriptionOnUpdateTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onUpdateTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  ResolverSubscriptionOnDeleteTodo:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onDeleteTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
Outputs:
  GraphQLApiId:
    Description: 'AppSync GraphQL API identifier'
    Value: !GetAtt GraphQLApi.ApiId

  GraphQLApiUrl:
    Description: 'AppSync GraphQL API endpoint URL'
    Value: !GetAtt GraphQLApi.GraphQLUrl

  GraphQLApiArn:
    Description: 'AppSync GraphQL API ARN'
    Value: !GetAtt GraphQLApi.Arn

  ApiKey:
    Description: 'API key for the TodoAPIwithJs GraphQL API'
    Value: !GetAtt GraphQLApiKey.ApiKey

  TableName:
    Description: 'DynamoDB Todo table name'
    Value: !Ref TodoTable

AWSTemplateFormatVersion: '2010-09-09'
Description: >
  SimpleTodoAPI - AWS AppSync GraphQL API for a simple to-do list, backed by a DynamoDB
  table and implemented entirely with JavaScript (APPSYNC_JS) unit resolvers.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table: primary key id, GSI owner-index (owner HASH, createdAt RANGE)
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
        - AttributeName: createdAt
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: createdAt
              KeyType: RANGE
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  # ---------------------------------------------------------------------------
  # Service role assumed by AppSync to read/write the todo table
  # ---------------------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to read and write the SimpleTodoAPI DynamoDB table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: SimpleTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/owner-index'

  # ---------------------------------------------------------------------------
  # AppSync API, schema and API key
  # ---------------------------------------------------------------------------
  SimpleTodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Description: API key used to exercise the SimpleTodoAPI

  SimpleTodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }

        input CreateTodoInput {
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  # ---------------------------------------------------------------------------
  # Single DynamoDB data source used by every resolver
  # ---------------------------------------------------------------------------
  SimpleTodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the SimpleTodoAPI todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref 'AWS::Region'

  # ---------------------------------------------------------------------------
  # Mutation.createTodo
  # ---------------------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt SimpleTodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();

          const identity = ctx.identity || {};
          let owner = identity.username || identity.sub;
          if (!owner && identity.claims) {
            owner = identity.claims.sub || identity.claims.username;
          }
          if (!owner) {
            owner = 'anonymous';
          }

          const todo = {
            id: util.autoId(),
            owner: owner,
            title: input.title,
            completed: (input.completed === undefined || input.completed === null) ? false : input.completed,
            createdAt: now,
            updatedAt: now,
          };

          if (input.description !== undefined && input.description !== null) {
            todo.description = input.description;
          }

          ctx.stash.todo = todo;

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: todo.id }),
            attributeValues: util.dynamodb.toMapValues(todo),
            condition: {
              expression: 'attribute_not_exists(id)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          if (ctx.result && ctx.result.id) {
            return ctx.result;
          }
          return ctx.stash.todo;
        }

  # ---------------------------------------------------------------------------
  # Mutation.updateTodo
  # ---------------------------------------------------------------------------
  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt SimpleTodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;

          const expressionNames = { '#updatedAt': 'updatedAt' };
          const expressionValues = { ':updatedAt': util.time.nowISO8601() };
          const sets = ['#updatedAt = :updatedAt'];

          if (input.title !== undefined && input.title !== null) {
            expressionNames['#title'] = 'title';
            expressionValues[':title'] = input.title;
            sets.push('#title = :title');
          }

          if (input.description !== undefined && input.description !== null) {
            expressionNames['#description'] = 'description';
            expressionValues[':description'] = input.description;
            sets.push('#description = :description');
          }

          if (input.completed !== undefined && input.completed !== null) {
            expressionNames['#completed'] = 'completed';
            expressionValues[':completed'] = input.completed;
            sets.push('#completed = :completed');
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Mutation.deleteTodo
  # ---------------------------------------------------------------------------
  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt SimpleTodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Query.getTodo
  # ---------------------------------------------------------------------------
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt SimpleTodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
